// Function to decode jfen into a 2D board (0 empty, 1 ball)
vector<vector<int>> decode(const string& jfen, int H, int W) {
    vector<vector<int>> board(H, vector<int>(W, 0));
    stringstream ss(jfen);
    string row;
    int r = 0;
    while (getline(ss, row, '/')) {
        int c = 0;
        size_t i = 0;
        while (i < row.size()) {
            if (row[i] == 'b') {
                board[r][c] = 1;
                c++;
                i++;
            } else {
                int num = 0;
                while (i < row.size() && isdigit(row[i])) {
                    num = num * 10 + (row[i] - '0');
                    i++;
                }
                c += num;
            }
        }
        r++;
    }
    return board;
}

// Function to encode board back to jfen
string encode(const vector<vector<int>>& board) {
    string jfen;
    for (size_t r = 0; r < board.size(); r++) {
        if (r > 0) jfen += '/';
        int empty_count = 0;
        for (int c = 0; c < (int)board[r].size(); c++) {
            if (board[r][c] == 0) {
                empty_count++;
            } else {
                if (empty_count > 0) {
                    jfen += to_string(empty_count);
                    empty_count = 0;
                }
                jfen += 'b';
            }
        }
        if (empty_count > 0) {
            jfen += to_string(empty_count);
        }
    }
    return jfen;
}

