        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        String[] rows = jfen.split("/");

        // Convert each row from jfen to explicit cell representation
        // '.' = empty, 'b' = ball
        List<char[]> board = new ArrayList<>();
        int width = -1;

        for (String row : rows) {
            ArrayList<Character> cells = new ArrayList<>();
            int i = 0;
            while (i < row.length()) {
                char ch = row.charAt(i);
                if (ch == 'b') {
                    cells.add('b');
                    i++;
                } else {
                    int num = 0;
                    while (i < row.length() && Character.isDigit(row.charAt(i))) {
                        num = num * 10 + (row.charAt(i) - '0');
                        i++;
                    }
                    for (int k = 0; k < num; k++) cells.add('.');
                }
            }
            char[] arr = new char[cells.size()];
            for (int i2 = 0; i2 < cells.size(); i2++) arr[i2] = cells.get(i2);
            if (width == -1) width = arr.length;
            board.add(arr);
        }

        // Apply move (1-indexed)
        board.get(a - 1)[b - 1] = '.';
        board.get(c - 1)[d - 1] = 'b';

        // Convert back to jfen
        StringBuilder ans = new StringBuilder();
        for (int r = 0; r < board.size(); r++) {
            if (r > 0) ans.append('/');
            char[] row = board.get(r);
            int emptyCount = 0;
            for (int col = 0; col < row.length; col++) {
                if (row[col] == '.') {
                    emptyCount++;
                } else {
                    if (emptyCount > 0) {
                        ans.append(emptyCount);
                        emptyCount = 0;
                    }
                    ans.append('b');
                }
            }
            if (emptyCount > 0) ans.append(emptyCount);
        }

        System.out.println(ans.toString());
    }
}

def parse_jfen(jfen, H, W):
    rows = jfen.split('/')
    board = []
    for row in rows:
        r = []
        i = 0
        while i < len(row):
            if row[i].isdigit():
                num = ''
                while i < len(row) and row[i].isdigit():
                    num += row[i]
                    i += 1
                r.extend([0] * int(num))
            else:
                r.append(1)
                i += 1
        board.append(r)
    return board

def board_to_jfen(board):
    rows = []
    for row in board:
        s = []
        count = 0
        for cell in row:
            if cell == 0:
                count += 1
            else:
                if count > 0:
                    s.append(str(count))
                    count = 0
                s.append('b')
        if count > 0:
            s.append(str(count))
        rows.append(''.join(s))
    return '/'.join(rows)

